// TH15 v1.00b st03mbs.ecl.txt MBossCard1 (208-264) + MBossCard1_at (266-346).
// Card t0 = source timerReset (line221, sub-time 4). Source window 1320 from there;
// first volley at sub-time 94 = 90 frames after the reset = card 210 after the shell buffer.
const TIME_LIMIT: int = 1444;
const SOURCE_LIMIT: int = 1320;
const OPENING_BUFFER: int = 120;
const PREATTACK: int = 90;

// MBossCard1_at: one emitter configuration, 32-or-16 volleys spaced 1-2 frames.
sub card_at(start: angle, step: angle) {
    var rank: int = global(GVAR_RANK);
    var cx: fx = $player_x;   // source 269/321: PLAYER_X2/Y2 aliases of the player position
    var cy: fx = $player_y;
    if rank >= 2 {
        // Source 271-284 HL branch: clamp the absolute emitter point.
        if cy < 128fx { cy = 128fx; }
        if cy >= 384fx { cy = 384fx; }
        if cx >= 128fx { cx = 128fx; }
        if cx < -128fx { cx = -128fx; }
    }
    // Source 325: etAngle(0, ANGLE_PLAYER, 1.0) read once at configuration time.
    var alpha: angle = aim_player();
    var n: int = 4;            // Source 288-297 etCount(0,N,1)
    if rank == 1 { n = 8; }
    if rank == 2 { n = 10; }
    if rank == 3 { n = 12; }
    var iters: int = 16;       // Source 327 diffI(E,16,16,32,32)
    var pause: int = 2;        // Source 333-342 per-volley wait 2/2/1/1
    if rank >= 2 { iters = 32; pause = 1; }
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 1);   // Source 287 etSprite(0,8,1)
    sh_aim(0, 0);
    sh_ring(0, 1);                // Source 286 etAim(0,3): fixed-direction full ring
    sh_count(0, n, 1);            // Source 297 etCount(layers=1)
    sh_angle(0, alpha, 0deg);
    sh_speed(0, 1fx, 0fx);        // Source 319 etSpeed(0,1.0,0.0): M=1 keeps 1px/frame
    sh_dist(0, -4fx);             // Source 318 etEx ANIM a=1: position -= 4*velocity
    sh_offset_abs(0, cx, cy);     // Source 321/323 etOffsetAbs(C,D)
    var a: angle = alpha + start;
    for i in 0..iters {
        // Source 330: etOffsetRad(A, -128) == radius128 at A+pi.
        sh_offset_rad(0, a + 180deg, 128fx);
        a = a + step;             // Source 331: A += B/16
        sh_fire(0);               // Source 332 etOn(0)
        card_wait(pause);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source t0..t89: 60-frame entry move to (0,144) (zero displacement from the
    // initialized position) plus the gate to sub-time 94; no emission before t94.
    card_wait(PREATTACK);
    var until: int = $frame+SOURCE_LIMIT-PREATTACK;
    loop {
        if $frame >= until { return; }
        card_at(0deg - 90deg, 11.25deg);    // Source 255: at(-pi/2, +pi)
        card_move_rand();                   // Source 256 moveRand(60,4,1.0)
        card_wait(120);                     // Source 257
        if $frame >= until { return; }
        card_at(90deg, 0deg - 11.25deg);    // Source 258: at(+pi/2, -pi)
        card_move_rand();                   // Source 259
        card_wait(120);                     // Source 260
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);   // Source MBoss setHitbox(40,40): native ordinary circle uses width*0.5
    set_hurtbox(24fx);  // Source setHurtbox(48,48); damage path disabled by invulnerability
    spell_begin(0, 22, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 144fx, 1600, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// st03mbs.ecl.txt:256/259 moveRand(60,4,1.0f) under moveLimit(0,128,280,64) (line247).
// Recipe reused from transcribe/th16/movement.md (verified source sample); limits adapted:
// position clamp x[-140,140] y[96,160], direction inner region x+-70, y112..144.
// int slot0 = next-step count; fx slots0/1 = logical unit direction. Same owner task only.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source +/-pi/2 guard, epsilon 0.05rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
